const kmB=(a,b)=>{const R=6371,d=Math.PI/180,x=Math.sin((b[0]-a[0])*d/2)**2+Math.cos(a[0]*d)*Math.cos(b[0]*d)*Math.sin((b[1]-a[1])*d/2)**2;return 2*R*Math.asin(Math.sqrt(x))};
