 const known=ds.filter(fresh).map(d=>({d,k:kmB(d.loc,[r.from.lat,r.from.lng])})).filter(x=>x.k<=R).sort((a,b)=>a.k-b.k),unk=ds.filter(d=>!fresh(d)).map(d=>({d}));r.notified=[];
