'POST admin'(b){const user=String(b.user||'').trim().toLowerCase(),name=String(b.name||'').trim().slice(0,40);if(!/^[a-z0-9_.]{3,20}$/.test(user)||user==='owner'||!name)throw E(400,'اسم المستخدم 3-20 حرفاً إنجليزياً/أرقاماً، والاسم مطلوب');if(!['manager','finance','support'].includes(b.role))throw E(400,'دور غير معروف');if(Object.values(db.admins).some(a=>a.user===user))throw E(409,'اسم المستخدم مستخدم');const pw=rnd(10,'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789'),id='ad'+db.seq++;db.admins[id]={id,name,user,role:b.role,pass:hash(pw),active:true,created:now()};aud('admin_account_create',null,{target:id,user,role:b.role});save();return{id,user,password:pw}},
'POST admin/:id'(b,id){const a=db.admins[id];if(!a)throw E(404,'غير موجود');const ch={};if(b.active!==undefined){ch.active=[a.active,!!b.active];a.active=!!b.active;for(const[t,v]of atok)if(v.acct&&v.acct.id===id)atok.delete(t)}if(['manager','finance','support'].includes(b.role)){ch.role=[a.role,b.role];a.role=b.role}let pw;if(b.resetPassword){pw=rnd(10,'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789');a.pass=hash(pw);for(const[t,v]of atok)if(v.acct&&v.acct.id===id)atok.delete(t);ch.password='reset'}aud('admin_account_update',null,{target:id,changes:ch});save();return pw?{password:pw}:{ok:1}},
'POST mypass'(b){const a=db.admins[CTX.admin&&CTX.admin.id];if(!a)throw E(400,'حساب المالك تُغيَّر كلمة سره من متغير ADMIN_PASSWORD في Render');if(!check(String(b.old||''),a.pass))throw E(400,'كلمة السر الحالية غير صحيحة');if(String(b.new||'').length<8)throw E(400,'8 أحرف على الأقل');a.pass=hash(b.new);aud('admin_password_change',null,{});save();return{ok:1}},
