const spend=u=>R2((u.wallet||0)+(u.promo||0));
function led(u,fld,type,amt,note,ref,balAfter){amt=R2(amt);if(!amt)return;const L=db.ledgers[u.id]=db.ledgers[u.id]||[];L.push({i:L.length?L[L.length-1].i+1:1,at:now(),f:fld,t:type,a:amt,bal:balAfter!==undefined?balAfter:R2(u[fld==='promo'?'promo':fld==='wallet'?'wallet':'bal']||0),n:String(note||'').slice(0,120),ref,by:CTX.admin&&CTX.admin.name||undefined});if(L.length>3000)L.splice(0,L.length-3000)}
const stmt=u=>({user:{id:u.id,name:u.name,role:u.role,phone:u.phone},balances:{wallet:u.wallet||0,promo:u.promo||0,bal:u.bal||0},entries:(db.ledgers[u.id]||[]).slice(-500).reverse()});
