const KINDS={welcome:'بونص ترحيبي',appreciation:'بونص تقدير',special:'مكافأة خاصة',incentive:'مكافأة تحفيزية'};
const campUsers=c=>c.target==='one'||c.target==='group'?(c.uids||[]).map(i=>db.users[i]).filter(u=>u&&u.status!=='deleted'&&u.status!=='blocked'&&u.role!=='agent'):Object.values(db.users).filter(u=>u.status!=='blocked'&&u.status!=='deleted'&&(c.target==='all'?u.role!=='agent':u.role===(c.target==='driver'?'driver':'rider')));
function grantCampaign(c){if(c.status!=='active')return 0;if(c.end&&c.end<now()){c.status='expired';return 0}let n=0;c.grants=c.grants||{};for(const u of campUsers(c)){const g=c.grants[u.id]||{n:0,amt:0};if(g.n>=c.maxUses)continue;grantBonus(u,c.amount,c.kind==='welcome'?'welcome':'appreciation',c.title,c.nw&&u.role==='rider',{cid:c.id,title:c.title,desc:c.desc,end:c.end,label:KINDS[c.kind]});c.grants[u.id]={n:g.n+1,amt:R2(g.amt+c.amount),at:now()};n++}c.granted=(c.granted||0)+n;return n}
function newCampaign(b,by){const amount=R2(+b.amount),title=String(b.title||'').trim().slice(0,60);if(!(amount>0)||!title)throw E(400,'العنوان والمبلغ مطلوبان');const kind=KINDS[b.kind]?b.kind:'appreciation',tg=['rider','driver','all','one','group'].includes(b.target)?b.target:'rider';let uids=[];if(tg==='one'){uids=[b.uid]}else if(tg==='group'){uids=(Array.isArray(b.uids)?b.uids:[]).slice(0,500)}if((tg==='one'||tg==='group')&&!uids.some(i=>db.users[i]))throw E(404,'اختر مستخدمين');const start=+b.start||now(),end=+b.end||undefined;if(end&&end<=start)throw E(400,'تاريخ النهاية قبل البداية');const id='c'+db.seq++,c=db.campaigns[id]={id,title,desc:String(b.desc||'').slice(0,200),kind,amount,target:tg,uids,start,end,maxUses:Math.min(100,Math.max(1,+b.maxUses||1)),nw:!!b.nonWithdrawable,status:start>now()?'pending':'active',by:by?{id:by.id,name:by.name}:undefined,at:now(),grants:{},granted:0};const n=c.status==='active'?grantCampaign(c):0;aud('admin_campaign_create',null,{id,title,kind,amount,target:tg,start,end,maxUses:c.maxUses,granted:n});save();return{id,granted:n,status:c.status}}
const ct=setInterval(()=>{let ch=false;for(const c of Object.values(db.campaigns)){if(c.status==='pending'&&c.start<=now()){c.status='active';grantCampaign(c);ch=true}else if(c.status==='active'&&c.end&&c.end<now()){c.status='expired';ch=true}}if(ch)save()},+process.env.CAMP_MS||30000);ct.unref();
