'POST agent/invite'(u,b){need(u,'agent');limited('inv:'+u.id,40,3600000);if(u.status!=='active')throw E(403,'حسابك موقوف');const p=normPhone(b.phone,u.country);if(Object.values(db.users).some(x=>x.phone===p))throw E(409,'هذا الرقم مسجل بالفعل في التطبيق');const old=db.invites[p];if(old&&old.agentId!==u.id&&['invited','registered'].includes(old.status))throw E(409,'هذا الرقم مدعو من وكيل آخر');db.invites[p]={phone:p,agentId:u.id,name:String(b.name||'').trim().slice(0,40),at:now(),status:'invited'};aud('agent_invite',u.id,{phone:p});save();return{invite:db.invites[p],link:'/?agent='+u.code}},
