'GET devices'(){const q=(Q.get('q')||'').toLowerCase().trim();const rows=Object.values(db.users).filter(u=>u.devs&&u.devs.length).flatMap(u=>u.devs.map(d=>({uid:u.id,name:u.name,phone:u.phone,role:u.role,status:u.status,model:d.model,os:d.os,devId:d.id,first:d.first,last:d.last,ip:d.ip}))).filter(r=>!q||[r.name,r.phone,r.model,r.os,r.devId].some(x=>String(x||'').toLowerCase().includes(q)));return{devices:rows.sort((a,b)=>(b.last||0)-(a.last||0)).slice(0,300)}},
