function match(tbl,m,url){for(const k in tbl){const[km,kp]=k.split(' ');if(km!==m)continue;const a=kp.split('/'),b=url.split('/');if(a.length!==b.length)continue;const ids=[];if(a.every((x,i)=>x[0]===':'?(ids.push(decodeURIComponent(b[i])),1):x===b[i]))return[tbl[k],ids,k]}return[]}
